from html.parser import HTMLParser
from pathlib import Path
class Extract(HTMLParser):
 def __init__(self): super().__init__(); self.parts=[]; self.skip=0
 def handle_starttag(self,t,a):
  if t in ('script','style'): self.skip+=1
  if t in ('p','br','li','tr','h1','h2','h3','td','th'): self.parts.append('\\n')
 def handle_endtag(self,t):
  if t in ('script','style'): self.skip-=1
 def handle_data(self,d):
  if not self.skip:self.parts.append(d)
for p in sorted(Path('.').glob('*.html')):
 e=Extract();e.feed(p.read_text()); lines=[s.strip() for s in ''.join(e.parts).splitlines() if s.strip()];Path('evidence',p.stem+'.txt').write_text('\\n'.join(lines)+'\\n')
